/* Mobile drawer accordion for the header menu (≤1100px only).
   Each top-level parent gets a separate +/− button; only one submenu is open
   at a time, and the parent's label always navigates. Without this script the
   drawer shows every submenu expanded, which is also what the Design canvas draws. */
(function () {
  var nav = document.querySelector('[data-bz-node="header-nav"] .bz-nav');
  if (!nav) return;
  var mobile = window.matchMedia('(max-width: 1100px)');
  var items = Array.prototype.filter.call(nav.children, function (li) {
    return li.classList.contains('bz-navitem--has-sub');
  });
  if (!items.length) return;

  function setExpanded(li, open) {
    li.classList.toggle('is-expanded', open);
    var btn = li.querySelector(':scope > .bz-subtoggle');
    btn.setAttribute('aria-expanded', String(open));
    btn.setAttribute('aria-label', (open ? 'Collapse ' : 'Expand ') + btn.getAttribute('data-label'));
  }

  items.forEach(function (li, i) {
    var link = li.querySelector(':scope > a');
    var sub = li.querySelector(':scope > .bz-subnav');
    if (!link || !sub) return;
    sub.id = sub.id || 'header-subnav-' + i;
    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'bz-subtoggle';
    btn.setAttribute('aria-controls', sub.id);
    btn.setAttribute('data-label', link.textContent.trim());
    link.after(btn);
    setExpanded(li, false);
    btn.addEventListener('click', function () {
      var open = !li.classList.contains('is-expanded');
      items.forEach(function (other) { if (other !== li) setExpanded(other, false); });
      setExpanded(li, open);
    });
  });
  nav.classList.add('is-accordion');

  /* widgets.js turns the first tap on a parent link into "open the dropdown"
     on touch screens. In the drawer the button does that, so let the label
     navigate: mark the item open before that handler sees the click, then
     clear the mark once the click has passed. */
  var marked = null;
  nav.addEventListener('click', function (event) {
    if (!mobile.matches) return;
    var link = event.target.closest('a');
    var li = link && link.parentElement;
    if (!li || items.indexOf(li) < 0 || li.hasAttribute('data-open')) return;
    li.setAttribute('data-open', '');
    marked = li;
  }, true);
  nav.addEventListener('click', function () {
    if (marked) { marked.removeAttribute('data-open'); marked = null; }
  });
})();
